{"version":3,"file":"ui-detailed.min.js","sources":["../../../src/local/courseai/ui-detailed.js"],"sourcesContent":["// This file is part of Moodle - http://moodle.org/\n//\n// Moodle is free software: you can redistribute it and/or modify\n// it under the terms of the GNU General Public License as published by\n// the Free Software Foundation, either version 3 of the License, or\n// (at your option) any later version.\n//\n// Moodle is distributed in the hope that it will be useful,\n// but WITHOUT ANY WARRANTY; without even the implied warranty of\n// MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n// GNU General Public License for more details.\n//\n// You should have received a copy of the GNU General Public License\n// along with Moodle.  If not, see <http://www.gnu.org/licenses/>.\n\n/**\n * Detailed planning UI — thin composition root.\n *\n * @module     local_coursegen/local/courseai/ui-detailed\n * @copyright  2026 Wilber Narvaez <https://datacurso.com>\n * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later\n */\n\nimport DeleteCancelModal from 'core/modal_delete_cancel';\nimport ModalEvents from 'core/modal_events';\nimport {createTextPanel} from 'local_coursegen/local/courseai/ui/panel';\nimport {focusChange, markRemoving} from 'local_coursegen/local/courseai/ui/highlight';\nimport {normalizeInitialSections} from './detailed/normalize';\nimport {\n    initDetailedPlanView,\n    finalizePlanView,\n    handleDetailedPlanField,\n    handleDetailedPlanActivity,\n    syncDetailedStructureFromSections,\n    enableAllActionControls,\n    reconcilePlan,\n} from './detailed/view';\nimport {updateDetailedHeaderStats} from './detailed/badges';\nimport {markProposalTargetPending} from './detailed/pending';\n\n/**\n * Build the confirmDelete helper bound to DeleteCancelModal.\n *\n * @param {Object} options\n * @param {string} options.title\n * @param {string} options.body\n * @returns {Promise<boolean>}\n */\nconst buildConfirmDelete = async({title, body}) => {\n    const modal = await DeleteCancelModal.create({title, body});\n\n    return await new Promise((resolve) => {\n        let resolved = false;\n\n        modal.getRoot().on(ModalEvents.delete, () => {\n            resolved = true;\n            resolve(true);\n        });\n\n        modal.getRoot().on(ModalEvents.hidden, () => {\n            if (!resolved) {\n                resolve(false);\n            }\n            modal.destroy();\n        });\n\n        modal.show();\n    });\n};\n\n/**\n * Create detailed planning helpers.\n *\n * @param {Object} deps\n * @param {Object} deps.state\n * @param {Object} deps.elements\n * @param {Object} deps.activityLabels\n * @param {Function} deps.getActivityIconUrl\n * @param {Function} deps.escapeHtml\n * @param {Function} deps.switchPlanMode\n * @param {Function} deps.setProgress\n * @param {Object} deps.texts\n * @param {Function} deps.formatTemplate\n * @param {Function} deps.runPlanAction\n * @param {Function} [deps.emitLog]\n * @returns {Object}\n */\nexport const createDetailedUi = (deps) => {\n    const {\n        state,\n        elements,\n        activityLabels,\n        getActivityIconUrl,\n        escapeHtml,\n        switchPlanMode,\n        setProgress,\n        texts,\n        formatTemplate,\n        runPlanAction,\n        emitLog,\n    } = deps;\n\n    /**\n     * Emit a log entry if emitLog is wired.\n     *\n     * @param {Object} params\n     */\n    const log = (params) => {\n        if (typeof emitLog === 'function') {\n            emitLog(params);\n        }\n    };\n\n    /** Shared context object threaded through all module functions. */\n    const ctx = {\n        state,\n        elements,\n        activityLabels,\n        getActivityIconUrl,\n        escapeHtml,\n        switchPlanMode,\n        setProgress,\n        texts,\n        formatTemplate,\n        runPlanAction,\n        log,\n        confirmDelete: buildConfirmDelete,\n        createTextPanel,\n        focusChange,\n        markRemoving,\n    };\n\n    return {\n        normalizeInitialSections: (sections) => normalizeInitialSections(ctx, sections),\n        initDetailedPlanView: (data) => initDetailedPlanView(ctx, data),\n        finalizePlanView: () => finalizePlanView(ctx),\n        handleDetailedPlanField: (data) => handleDetailedPlanField(ctx, data),\n        handleDetailedPlanActivity: (data) => handleDetailedPlanActivity(ctx, data),\n        syncDetailedStructureFromSections: (sections) => syncDetailedStructureFromSections(ctx, sections),\n        updateDetailedHeaderStats: () => updateDetailedHeaderStats(ctx),\n        enableAllActionControls: () => enableAllActionControls(ctx),\n        reconcilePlan: (currentPlan) => reconcilePlan(ctx, currentPlan),\n        markProposalTargetPending: (intent) => markProposalTargetPending(ctx, intent),\n    };\n};\n"],"names":["buildConfirmDelete","async","title","body","modal","DeleteCancelModal","create","Promise","resolve","resolved","getRoot","on","ModalEvents","delete","hidden","destroy","show","deps","state","elements","activityLabels","getActivityIconUrl","escapeHtml","switchPlanMode","setProgress","texts","formatTemplate","runPlanAction","emitLog","ctx","log","params","confirmDelete","createTextPanel","focusChange","markRemoving","normalizeInitialSections","sections","initDetailedPlanView","data","finalizePlanView","handleDetailedPlanField","handleDetailedPlanActivity","syncDetailedStructureFromSections","updateDetailedHeaderStats","enableAllActionControls","reconcilePlan","currentPlan","markProposalTargetPending","intent"],"mappings":";;;;;;;0NAgDMA,mBAAqBC,MAAAA,WAAMC,MAACA,MAADC,KAAQA,iBAC/BC,YAAcC,6BAAkBC,OAAO,CAACJ,MAAAA,MAAOC,KAAAA,oBAExC,IAAII,SAASC,cAClBC,UAAW,EAEfL,MAAMM,UAAUC,GAAGC,sBAAYC,QAAQ,KACnCJ,UAAW,EACXD,SAAQ,MAGZJ,MAAMM,UAAUC,GAAGC,sBAAYE,QAAQ,KAC9BL,UACDD,SAAQ,GAEZJ,MAAMW,aAGVX,MAAMY,qCAqBmBC,aACvBC,MACFA,MADEC,SAEFA,SAFEC,eAGFA,eAHEC,mBAIFA,mBAJEC,WAKFA,WALEC,eAMFA,eANEC,YAOFA,YAPEC,MAQFA,MAREC,eASFA,eATEC,cAUFA,cAVEC,QAWFA,SACAX,KAcEY,IAAM,CACRX,MAAAA,MACAC,SAAAA,SACAC,eAAAA,eACAC,mBAAAA,mBACAC,WAAAA,WACAC,eAAAA,eACAC,YAAAA,YACAC,MAAAA,MACAC,eAAAA,eACAC,cAAAA,cACAG,IAlBSC,SACc,mBAAZH,SACPA,QAAQG,SAiBZC,cAAehC,mBACfiC,gBAAAA,uBACAC,YAAAA,uBACAC,aAAAA,+BAGG,CACHC,yBAA2BC,WAAa,uCAAyBR,IAAKQ,UACtEC,qBAAuBC,OAAS,8BAAqBV,IAAKU,MAC1DC,iBAAkB,KAAM,0BAAiBX,KACzCY,wBAA0BF,OAAS,iCAAwBV,IAAKU,MAChEG,2BAA6BH,OAAS,oCAA2BV,IAAKU,MACtEI,kCAAoCN,WAAa,2CAAkCR,IAAKQ,UACxFO,0BAA2B,KAAM,qCAA0Bf,KAC3DgB,wBAAyB,KAAM,iCAAwBhB,KACvDiB,cAAgBC,cAAgB,uBAAclB,IAAKkB,aACnDC,0BAA4BC,SAAW,sCAA0BpB,IAAKoB"}
